(function() {
    'use strict';

    class BlueShiftAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'BlueShift';
            this.version = '1.1.0';
            this.ROUNDS = [
                { key: 'r1' },
                { key: 'r2' },
                { key: 'r3' },
                { key: 'r4' },
                { key: 'r5' }
            ];
            this.THEMES = {
                rural: {
                    eliminate: ['brand_advertising', 'customization'],
                    reduce:    ['sales_force', 'geo_reach', 'delivery_speed'],
                    raise:     ['technical_support', 'reliability'],
                    create:    ['rural_financing'],
                    tier:      'tier2',
                    segment:   'rural_homebuilders'
                },
                sustainability: {
                    eliminate: ['customization', 'brand_advertising'],
                    reduce:    ['geo_reach', 'sales_force'],
                    raise:     ['sustainability'],
                    create:    ['carbon_dashboard'],
                    tier:      'tier3',
                    segment:   'esg_buyers'
                },
                smallContractor: {
                    eliminate: ['regional_offices', 'brand_advertising'],
                    reduce:    ['delivery_speed', 'sales_force'],
                    raise:     ['technical_support', 'reliability'],
                    create:    ['modular_delivery'],
                    tier:      'tier1',
                    segment:   'small_contractors'
                }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 80,
                    incumbentRevenue: 600,
                    blueOceanRevenue: 0,
                    totalScore: 0,
                    strategicCoherence: 0,
                    financialViability: 0,
                    executionFeasibility: 0,
                    innovation: 0,
                    redOceanIndex: 0,
                    strategicTheme: null,
                    bestThemeMatches: 0,
                    eliminate: null,
                    reduce: null,
                    raise: null,
                    create: null,
                    tier: null,
                    segment: null,
                    pricing: null,
                    investment: 0,
                    partner: null,
                    tamRealism: 0,
                    orgDesign: null,
                    changeSpeed: null,
                    commInvestment: 0,
                    scoreHistory: [],
                    revenueHistory: [],
                    coherenceHistory: [],
                    viabilityHistory: [],
                    executionHistory: [],
                    innovationHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    rivalry: 7,
                    buyer: 6,
                    supplier: 4,
                    substitute: 5,
                    entrants: 3,
                    eliminate: 'brand_advertising',
                    reduce: 'sales_force',
                    raise: 'technical_support',
                    create: 'rural_financing',
                    tier: 'tier2',
                    segment: 'rural_homebuilders',
                    tam: 80,
                    pricing: 'parity',
                    investment: 20,
                    partner: 'solo',
                    orgDesign: 'separate',
                    changeSpeed: 'moderate',
                    commInvestment: 3
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var period = state.currentPeriod || 1;
            var read = function(id) {
                var el = document.getElementById(id);
                return el ? el.value : null;
            };
            var num = function(id) {
                var el = document.getElementById(id);
                return el ? parseFloat(el.value) : NaN;
            };

            if (period === 1) {
                decisions.rivalry = num('rivalryInput');
                decisions.buyer = num('buyerInput');
                decisions.supplier = num('supplierInput');
                decisions.substitute = num('substituteInput');
                decisions.entrants = num('entrantsInput');
                var forces = [decisions.rivalry, decisions.buyer, decisions.supplier, decisions.substitute, decisions.entrants];
                for (var i = 0; i < forces.length; i++) {
                    if (isNaN(forces[i]) || forces[i] < 1 || forces[i] > 10) {
                        window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_forces'), 'warning');
                        return false;
                    }
                }
            } else if (period === 2) {
                decisions.eliminate = read('eliminateInput');
                decisions.reduce = read('reduceInput');
                decisions.raise = read('raiseInput');
                decisions.create = read('createInput');
                if (!decisions.eliminate || !decisions.reduce || !decisions.raise || !decisions.create) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_actions'), 'warning');
                    return false;
                }
            } else if (period === 3) {
                decisions.tier = read('tierInput');
                decisions.segment = read('segmentInput');
                decisions.tam = num('tamInput');
                if (!decisions.tier || !decisions.segment || isNaN(decisions.tam) || decisions.tam < 10) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_tier'), 'warning');
                    return false;
                }
            } else if (period === 4) {
                decisions.pricing = read('pricingInput');
                decisions.investment = num('investmentInput');
                decisions.partner = read('partnerInput');
                if (!decisions.pricing || !decisions.partner || isNaN(decisions.investment) || decisions.investment < 5) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_bm'), 'warning');
                    return false;
                }
                if (decisions.investment > state.domainState.cash) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_cash'), 'warning');
                    return false;
                }
            } else if (period === 5) {
                decisions.orgDesign = read('orgInput');
                decisions.changeSpeed = read('speedInput');
                decisions.commInvestment = num('commInput');
                if (!decisions.orgDesign || !decisions.changeSpeed || isNaN(decisions.commInvestment)) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_exec'), 'warning');
                    return false;
                }
                if (decisions.commInvestment > state.domainState.cash) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_cash'), 'warning');
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var results = { period: period };
            var event = '';
            var t = function(k) { return window.mySimulation.t(k); };

            if (period === 1) {
                var forceAvg = (d.rivalry + d.buyer + d.supplier + d.substitute + d.entrants) / 5;
                ds.redOceanIndex = Math.round(forceAvg * 10);
                var accuracy = 100;
                accuracy -= Math.abs(d.rivalry - 8.5) * 4;
                accuracy -= Math.abs(d.buyer - 7) * 4;
                accuracy -= Math.abs(d.supplier - 4) * 4;
                accuracy -= Math.abs(d.substitute - 5) * 4;
                accuracy -= Math.abs(d.entrants - 3) * 4;
                accuracy = Math.max(0, Math.min(100, Math.round(accuracy)));
                ds.innovation = Math.round(accuracy * 0.4);
                ds.strategicCoherence = Math.round(accuracy * 0.35);
                results.redOceanIndex = ds.redOceanIndex;
                results.diagnosisAccuracy = accuracy;
                results.profit = 0;
                event = forceAvg >= 6 ? t('fb_red_ocean') : t('fb_mild_ocean');
            } else if (period === 2) {
                ds.eliminate = d.eliminate;
                ds.reduce = d.reduce;
                ds.raise = d.raise;
                ds.create = d.create;
                var themeScores = this._scoreTheme(ds);
                ds.strategicTheme = themeScores.bestTheme;
                ds.bestThemeMatches = themeScores.bestMatches;
                var coherenceBoost = themeScores.bestMatches * 18;
                ds.strategicCoherence = Math.min(100, ds.strategicCoherence + coherenceBoost);
                var costImpact = this._costImpact(ds);
                ds.cash += costImpact;
                ds.innovation = Math.min(100, ds.innovation + (themeScores.bestMatches >= 3 ? 22 : 10));
                results.eliminate = d.eliminate;
                results.reduce = d.reduce;
                results.raise = d.raise;
                results.create = d.create;
                results.themeMatches = themeScores.bestMatches;
                results.costImpact = costImpact;
                results.profit = costImpact;
                event = themeScores.bestMatches >= 3 ? t('fb_theme_strong') : t('fb_theme_weak');
            } else if (period === 3) {
                ds.tier = d.tier;
                ds.segment = d.segment;
                var targetingMatch = 0;
                var themeDef = this.THEMES[ds.strategicTheme] || null;
                if (themeDef) {
                    if (themeDef.tier === d.tier) targetingMatch += 1;
                    if (themeDef.segment === d.segment) targetingMatch += 1;
                }
                var expTam = this._expectedTam(d.segment);
                var tamRealism = 100 - Math.abs(d.tam - expTam) * 0.6;
                tamRealism = Math.max(0, Math.min(100, Math.round(tamRealism)));
                ds.tamRealism = tamRealism;
                ds.strategicCoherence = Math.min(100, ds.strategicCoherence + targetingMatch * 14);
                ds.innovation = Math.min(100, ds.innovation + (d.tier === 'tier3' ? 15 : d.tier === 'tier2' ? 10 : 5));
                results.tier = d.tier;
                results.segment = d.segment;
                results.targetingMatch = targetingMatch;
                results.tamRealism = tamRealism;
                results.profit = 0;
                event = targetingMatch === 2 ? t('fb_target_match') : t('fb_target_drift');
            } else if (period === 4) {
                ds.pricing = d.pricing;
                ds.investment = d.investment;
                ds.partner = d.partner;
                ds.cash -= d.investment;
                var penetration = 0.05;
                if (ds.bestThemeMatches >= 3) penetration += 0.05;
                if (d.partner === 'partner') penetration += 0.03;
                var priceMult = d.pricing === 'premium' ? 1.2 : d.pricing === 'discount' ? 0.85 : 1.0;
                var marginPct = d.pricing === 'premium' ? 0.22 : d.pricing === 'discount' ? 0.08 : 0.14;
                if (ds.segment === 'esg_buyers' && d.pricing === 'premium') marginPct += 0.04;
                if (ds.segment === 'rural_homebuilders' && d.pricing === 'discount') marginPct += 0.03;
                if (d.partner === 'partner') marginPct -= 0.03;
                // Effective, defensible TAM: financials are based on the market size the
                // player can actually defend. As Round-3 sizing realism falls, the claimed TAM
                // is pulled back toward the segment's expected (defensible) TAM, so inflating
                // the market no longer buys financial viability. Realistic sizing uses it in full.
                var realism = (typeof ds.tamRealism === 'number') ? ds.tamRealism : 100;
                var defensibleTam = this._expectedTam(ds.segment);
                var effectiveTam = defensibleTam + (d.tam - defensibleTam) * (realism / 100);
                if (effectiveTam < 1) effectiveTam = 1;
                var year3Revenue = Math.round(effectiveTam * penetration * priceMult);
                var year3Margin = Math.round(year3Revenue * marginPct);
                ds.blueOceanRevenue = year3Revenue;
                var paybackYears = (d.investment > 0 && year3Margin > 0)
                    ? Math.round((d.investment / Math.max(1, year3Margin)) * 10) / 10
                    : 99;
                var viability = 0;
                if (year3Margin > 0) viability += 40;
                if (paybackYears < 3) viability += 30;
                else if (paybackYears < 5) viability += 15;
                if (marginPct >= 0.15) viability += 20;
                if (d.investment <= 35) viability += 10;
                ds.financialViability = Math.min(100, viability);
                ds.innovation = Math.min(100, ds.innovation + (d.pricing === 'premium' && ds.segment === 'esg_buyers' ? 10 : 5));
                results.pricing = d.pricing;
                results.investment = d.investment;
                results.partner = d.partner;
                results.year3Revenue = year3Revenue;
                results.year3Margin = year3Margin;
                results.paybackYears = paybackYears;
                results.profit = year3Margin - d.investment;
                event = viability >= 70 ? t('fb_fin_strong')
                      : viability >= 40 ? t('fb_fin_moderate')
                      : t('fb_fin_weak');
            } else if (period === 5) {
                ds.orgDesign = d.orgDesign;
                ds.changeSpeed = d.changeSpeed;
                ds.commInvestment = d.commInvestment;
                ds.cash -= d.commInvestment;
                var exec = 0;
                if (d.orgDesign === 'separate') exec += 35;
                else if (d.orgDesign === 'hybrid') exec += 25;
                else exec += 10;
                if (d.changeSpeed === 'moderate') exec += 30;
                else if (d.changeSpeed === 'gradual') exec += 20;
                else exec += 10;
                if (d.commInvestment >= 3 && d.commInvestment <= 8) exec += 25;
                else if (d.commInvestment > 8) exec += 15;
                else exec += 5;
                if (ds.bestThemeMatches >= 3) exec += 10;
                ds.executionFeasibility = Math.min(100, exec);
                ds.innovation = Math.min(100, ds.innovation + 5);
                results.orgDesign = d.orgDesign;
                results.changeSpeed = d.changeSpeed;
                results.commInvestment = d.commInvestment;
                results.executionScore = ds.executionFeasibility;
                results.profit = ds.blueOceanRevenue;
                event = ds.executionFeasibility >= 80 ? t('fb_exec_excellent')
                      : ds.executionFeasibility >= 60 ? t('fb_exec_good')
                      : t('fb_exec_needs_work');
            }

            var finalScore = Math.round(
                ds.strategicCoherence * 0.30 +
                ds.financialViability * 0.30 +
                ds.executionFeasibility * 0.25 +
                ds.innovation * 0.15
            );
            ds.totalScore = finalScore;

            ds.scoreHistory.push(finalScore);
            ds.revenueHistory.push(ds.blueOceanRevenue);
            ds.coherenceHistory.push(ds.strategicCoherence);
            ds.viabilityHistory.push(ds.financialViability);
            ds.executionHistory.push(ds.executionFeasibility);
            ds.innovationHistory.push(ds.innovation);

            results.totalScore = finalScore;
            results.event = event;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 400);

            return results;
        }

        _scoreTheme(ds) {
            var best = 0;
            var bestTheme = null;
            var self = this;
            Object.keys(this.THEMES).forEach(function(name) {
                var theme = self.THEMES[name];
                var matches = 0;
                if (theme.eliminate.indexOf(ds.eliminate) >= 0) matches++;
                if (theme.reduce.indexOf(ds.reduce) >= 0) matches++;
                if (theme.raise.indexOf(ds.raise) >= 0) matches++;
                if (theme.create.indexOf(ds.create) >= 0) matches++;
                if (matches > best) {
                    best = matches;
                    bestTheme = name;
                }
            });
            return { bestMatches: best, bestTheme: bestTheme };
        }

        _costImpact(ds) {
            var elimMap = { brand_advertising: 8, regional_offices: 12, customization: 5 };
            var redMap = { delivery_speed: 6, sales_force: 10, geo_reach: 4 };
            var raiseMap = { sustainability: -8, technical_support: -6, reliability: -4 };
            var createMap = { carbon_dashboard: -10, rural_financing: -12, modular_delivery: -8 };
            var total = 0;
            total += elimMap[ds.eliminate] || 0;
            total += redMap[ds.reduce] || 0;
            total += raiseMap[ds.raise] || 0;
            total += createMap[ds.create] || 0;
            return total;
        }

        _expectedTam(segment) {
            if (segment === 'rural_homebuilders') return 120;
            if (segment === 'small_contractors') return 180;
            if (segment === 'esg_buyers') return 90;
            if (segment === 'modular_construction') return 60;
            return 100;
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(Math.max(period - 1, 0), this.ROUNDS.length - 1);
            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var briefKeys = ['brief_r1', 'brief_r2', 'brief_r3', 'brief_r4', 'brief_r5'];
            var titleKeys = ['r1_title', 'r2_title', 'r3_title', 'r4_title', 'r5_title'];
            if (titleEl && window.mySimulation) titleEl.innerHTML = window.mySimulation.t(titleKeys[idx]);
            if (textEl && window.mySimulation) textEl.innerHTML = window.mySimulation.t(briefKeys[idx]);
            for (var i = 1; i <= 5; i++) {
                var panel = document.getElementById('panelR' + i);
                if (panel) panel.style.display = (i === period) ? 'block' : 'none';
            }
        }

